SELECT analytics_order_facts.customer_segment, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 9 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'wholesale' AND analytics_order_facts.category = 'category_07' GROUP BY analytics_order_facts.customer_segment ORDER BY net_revenue DESC, analytics_order_facts.customer_segment ASC LIMIT 12
